use hawdb::{Database, QueryStreamOptions, Value};
use std::path::PathBuf;
use std::time::Instant;

const INSERT: &str = "INSERT INTO thread_messages (content_message_id, thread_storage_id, order_index, content, token_count) VALUES ($1, $2, $3, $4, $5)";
const POINT: &str = "SELECT content_message_id, thread_storage_id, order_index, content, token_count FROM thread_messages WHERE content_message_id = $1";
const PAGE: &str = "SELECT content_message_id, thread_storage_id, order_index, content, token_count FROM thread_messages WHERE thread_storage_id = $1 ORDER BY order_index, content_message_id LIMIT $2";

fn check(output: &hawdb::QueryOutput, thread: usize, message: usize, count: usize) {
    assert_eq!(output.rows.len(), count);
    for (offset, row) in output.rows.iter().enumerate() {
        let message = message + offset;
        assert_eq!(row.len(), 5);
        assert_eq!(row["content_message_id"], Value::String(format!("message-{thread:04}-{message:04}")));
        assert_eq!(row["thread_storage_id"], Value::String(format!("thread-{thread:04}")));
        assert_eq!(row["order_index"], Value::Int(message as i64));
        assert_eq!(row["content"], Value::String("x".repeat(1024)));
        assert_eq!(row["token_count"], Value::Int(256));
    }
}

fn main() {
    let path = PathBuf::from(std::env::args().nth(1).unwrap());
    let mut db = Database::open(&path).unwrap();
    db.query_sql("CREATE TABLE thread_messages (content_message_id TEXT PRIMARY KEY, thread_storage_id TEXT NOT NULL, order_index BIGINT NOT NULL, content TEXT NOT NULL, token_count BIGINT NOT NULL)").unwrap();
    db.query_sql("CREATE INDEX idx_thread_messages_order ON thread_messages (thread_storage_id, order_index, content_message_id)").unwrap();
    for thread in 0..128 {
        let mut tx = db.begin_transaction();
        for message in 0..128 {
            tx.query_sql_with_params(INSERT, &[Value::String(format!("message-{thread:04}-{message:04}")), Value::String(format!("thread-{thread:04}")), Value::Int(message), Value::String("x".repeat(1024)), Value::Int(256)]).unwrap();
        }
        tx.commit().unwrap();
    }
    db.checkpoint().unwrap();
    drop(db);
    let db = Database::open(&path).unwrap();
    let snapshot = db.begin_read_transaction();
    println!("round,case,requests,descriptor_reads,logical_pages,physical_pages,cache_hits,elapsed_nanos");
    for round in 0..3 {
        for page in [false, true] {
            let requests = if page {128} else {512};
            let mut descriptors = 0;
            let mut logical = 0;
            let mut physical = 0;
            let mut hits = 0;
            let started = Instant::now();
            for request in 0..requests {
                let thread = request * 13 % 128;
                let message = if page {0} else {request * 7 % 128};
                let parameters = if page {
                    vec![Value::String(format!("thread-{thread:04}")), Value::Int(32)]
                } else {
                    vec![Value::String(format!("message-{thread:04}-{message:04}"))]
                };
                let result = snapshot.query_sql_with_params_options_profiled(if page {PAGE} else {POINT}, &parameters, QueryStreamOptions::default()).unwrap();
                check(&result.output, thread, message, if page {32} else {1});
                assert!(result.profile.row_read.base_generation.is_some());
                descriptors += result.profile.row_read.descriptor_reads;
                logical += result.profile.row_read.logical_pages;
                physical += result.profile.row_read.physical_pages;
                hits += result.profile.row_read.cache_hits;
            }
            println!("{round},{},{requests},{descriptors},{logical},{physical},{hits},{}", if page {"page"} else {"point"}, started.elapsed().as_nanos());
        }
    }
    drop(snapshot);
    drop(db);
    let db = Database::open(&path).unwrap();
    let output = db.begin_read_transaction().query_sql("SELECT COUNT(*) AS count FROM thread_messages").unwrap();
    assert_eq!(output.rows[0]["count"], Value::Int(16384));
}
